--
-- Triggers `warehouse_stock`
--
DELIMITER $$
CREATE TRIGGER `trg_warehouse_stock_no_negative_insert` BEFORE INSERT ON `warehouse_stock` FOR EACH ROW BEGIN
    IF NEW.qty < -0.0001 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'warehouse_stock quantity cannot be negative';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_warehouse_stock_no_negative_update` BEFORE UPDATE ON `warehouse_stock` FOR EACH ROW BEGIN
    IF NEW.qty < -0.0001 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'warehouse_stock quantity cannot be negative';
    END IF;
END
$$
DELIMITER ;

